const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const project='bepxinh-b0be7',directory='node_modules/.cache/report-release';
const hash=s=>crypto.createHash('sha256').update(s.replace(/^\uFEFF/,'').replace(/\r\n/g,'\n')).digest('hex');
(async()=>{assert.ok(!process.env.FIRESTORE_EMULATOR_HOST);let lib;for(const entry of process.env.PATH.split(path.delimiter)){const p=path.resolve(entry,'../firebase-tools/lib');if(fs.existsSync(path.join(p,'gcp/rules.js'))){lib=p;break;}}assert.ok(lib);const auth=require(path.join(lib,'auth'));const options={project,nonInteractive:true};auth.setActiveAccount(options,auth.selectAccount('phuckk2101@gmail.com',process.cwd()));await require(path.join(lib,'requireAuth')).requireAuth(options);const rules=require(path.join(lib,'gcp/rules'));const release=(await rules.listAllReleases(project)).find(r=>r.name===`projects/${project}/releases/cloud.firestore`);assert.ok(release);const files=await rules.getRulesetContent(release.rulesetName);assert.equal(files.length,1);const {Client}=require(path.join(lib,'apiv2'));const api=new Client({urlPrefix:'https://firestore.googleapis.com',auth:true});const indexes=(await api.get(`/v1/projects/${project}/databases/(default)/collectionGroups/-/indexes`)).body.indexes;assert.equal(indexes.length,10);assert.ok(indexes.every(i=>i.state==='READY'));const result={project,checkedAt:new Date().toISOString(),release,remoteSha256:hash(files[0].content),localSha256:hash(fs.readFileSync('firestore.rules','utf8')),indexCount:indexes.length,allIndexesReady:true};if(process.argv.includes('--verify')){const before=JSON.parse(fs.readFileSync(path.join(directory,'before.json'),'utf8'));assert.equal(result.localSha256,before.localSha256);assert.equal(result.remoteSha256,result.localSha256);fs.writeFileSync(path.join(directory,'after.json'),JSON.stringify(result,null,2));}else{fs.writeFileSync(path.join(directory,'before.rules'),files[0].content);fs.writeFileSync(path.join(directory,'before.json'),JSON.stringify({...result,indexes},null,2));}console.log(JSON.stringify(result,null,2));})().catch(e=>{console.error(e.message);process.exitCode=1});
